/** Samples waiting to be sent to a partner laboratory — GET /api/v1/lab/send-outs/pending (who may call: holders of lab.sendout.manage). */
export function sendOutsPending(): Promise<SendOutPendingOut[]> {
  return api<SendOutPendingOut[]>("GET", `/lab/send-outs/pending`, undefined);
}

/** Send samples to a partner laboratory (the manifest) — POST /api/v1/lab/send-outs (who may call: holders of lab.sendout.manage). */
export function dispatch(body: SendOutIn): Promise<SendOutDetailOut> {
  return api<SendOutDetailOut>("POST", `/lab/send-outs`, body, { idempotent: true });
}

/** Send-out manifests — GET /api/v1/lab/send-outs (who may call: holders of lab.sendout.manage or diagnostics.quality.view). */
export function listSendOuts(query?: { partner_id?: number | null; outstanding?: boolean; limit?: number }): Promise<SendOutOut[]> {
  return api<SendOutOut[]>("GET", withQuery(`/lab/send-outs`, query), undefined);
}

/** A send-out manifest — GET /api/v1/lab/send-outs/{send_out_id} (who may call: holders of lab.sendout.manage or diagnostics.quality.view). */
export function getSendOut(send_out_id: number): Promise<SendOutDetailOut> {
  return api<SendOutDetailOut>("GET", `/lab/send-outs/${send_out_id}`, undefined);
}

/** The manifest to print for the courier — GET /api/v1/lab/send-outs/{send_out_id}/print-payload (who may call: holders of lab.sendout.manage). */
export function sendOutPrint(send_out_id: number): Promise<PrintOut_SendOutManifestFieldsOut_> {
  return api<PrintOut_SendOutManifestFieldsOut_>("GET", `/lab/send-outs/${send_out_id}/print-payload`, undefined);
}

/** Partner laboratories and imaging centres — GET /api/v1/diagnostic-partners (who may call: holders of diagnostics.setup.manage or diagnostics.quality.view or lab.sendout.manage or imaging.order.update or lab.test.manage). */
export function listPartners(query?: { services?: "Lab" | "Imaging" | null; active_only?: boolean }): Promise<PartnerOut[]> {
  return api<PartnerOut[]>("GET", withQuery(`/diagnostic-partners`, query), undefined);
}

/** Submit & Broadcast a result (goes to the verifier) — POST /api/v1/lab/items/{item_id}/results (who may call: holders of lab.result.enter). */
export function submitResult(item_id: number, body: ResultIn): Promise<LabResultOut> {
  return api<LabResultOut>("POST", `/lab/items/${item_id}/results`, body);
}

/** Reject an unusable sample (the test goes back to collection) — POST /api/v1/lab/samples/{sample_id}/reject (who may call: holders of lab.sample.receive or lab.sendout.manage). */
export function rejectSample(sample_id: number, body: SampleRejectIn): Promise<LabRequisitionDetailOut> {
  return api<LabRequisitionDetailOut>("POST", `/lab/samples/${sample_id}/reject`, body, { idempotent: true });
}
